-- chair-step: inverse of read_lane_v2_b3_43_mandate_definition — un-enrolls mandate.definition from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'mandate' and table_name = 'definition' and is_active);
select iam.apply_rls('mandate', 'definition', (select token from platform.entity_types where schema_name = 'mandate' and table_name = 'definition' and is_active), (select rls_variant from platform.entity_types where schema_name = 'mandate' and table_name = 'definition' and is_active));
